function budgetStatus(spentCents, budgetCents) {
  if (spentCents > budgetCents) {
    return "over";
  } else if (spentCents >= budgetCents * 0.8) {
    return "close";
  } else {
    return "ok";
  }
}

function amountLabel(amountCents) {
  return amountCents >= 10000 ? "big" : "small";
}

console.log(budgetStatus(1750, 2000));
console.log(amountLabel(12500));
